def api(name, svc, body_props, pre='', post='', desc='', timeout=20000, required=None):
    t = {"type": "function", "config": {"timeoutMs": timeout, "maxRetries": 0},
         "function": {"name": name, "handler": "__function__:api_call", "description": desc or name,
          "parameters": {"type": "object", "properties": {
            "url": {"type": "string", "default": BASE + svc}, "method": {"type": "string", "default": "POST"},
            "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
            "body": {"type": "object", "properties": body_props, "required": required or []}}}}}
    if pre: t["pre_process_code"] = pre
    if post: t["post_process_code"] = post
    return t
def eq(var, val): return {"variable": var, "operator": "equals", "operand": val}
def OR(*c): return {"logic": "or", "conditions": list(c)}
def AND(*c): return {"logic": "and", "conditions": list(c)}
def tr(target, desc, cond): return {"target_node": target, "description": desc, "condition": cond}
ALWAYS = {"operator": "always"}
def passnode(name, tool, transitions):
    return {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "pre_actions": [tool], "transitions": transitions}
def end(name, fn, text):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
            "terminal": {"type": "function", "function": {"name": fn, "handler": "__function__:end_call", "parameters": {"type": "object", "properties": {
                "message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": text}}}}}}
DATA = lambda props: {"data": {"type": "object", "properties": props}}

